# -*- coding: utf-8 -*-
BASE = r'C:\Users\Michael Song\Desktop\私人办公\A207123-任务C-显式公式与母函数\notes\report_parts'


def patch(name, pairs):
    path = BASE + '\\' + name
    s = open(path, encoding='utf-8').read()
    for a, b in pairs:
        n = s.count(a)
        assert n == 1, (name, a[:80], n)
        s = s.replace(a, b)
    open(path, 'w', encoding='utf-8').write(s)
    print('patched', name, len(pairs))


